123	void write_to_sd(ptr_t pa)
124	{
125	    int i;
126	    for(i = 0; i < DISK_PAGE_NUM; i++){
127	        if(disk_page[i].valid == 0){
128	            break;
129	        }
130	    }
131	    assert(i != DISK_PAGE_NUM);
132	    disk_page[i].valid = 1;
