                if(++bad>10) break;
                written[p][j]=0;
            }
        }
        uint64_t v=((uint64_t)p<<40)|((uint64_t)j<<24)|step;
        page[0]=v; page[511]=~v; model[p][j]=v; written[p][j]=1;
    }
    printf("seed %u: swapout=%ld swapin=%ld corruptions=%d free=%lu/%lu\n",seed,n_out,n_in,bad,free_page_num(),f0);
