static void boot_map(void){
    PTE *pgdir=(PTE*)pa2kva(PGDIR_PA);
    memset(pgdir,0,PAGE_SIZE);
    set_pfn(pgdir+0x101,(PGDIR_PA+NORMAL_PAGE_SIZE)>>NORMAL_PAGE_SHIFT); set_attribute(pgdir+0x101,_PAGE_PRESENT);
    PTE *l2=(PTE*)pa2kva(PGDIR_PA+NORMAL_PAGE_SIZE); memset(l2,0,PAGE_SIZE);
    for(int i=0;i<128;i++){ PTE*e=l2+0x80+i;
        set_pfn(e,(0x50000000+LARGE_PAGE_SIZE*i)>>NORMAL_PAGE_SHIFT);
        set_attribute(e,_PAGE_PRESENT|_PAGE_READ|_PAGE_WRITE|_PAGE_EXEC|_PAGE_ACCESSED|_PAGE_DIRTY); }
}
int main(void){
    host_arena=mmap(NULL,0x60000000lu-0x51000000lu,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS|MAP_NORESERVE,-1,0);
    sdcard=mmap(NULL,1lu<<26,PROT_READ|PROT_WRITE,MAP_PRIVATE|MAP_ANONYMOUS|MAP_NORESERVE,-1,0);
    boot_map();
    static pcb_t p; p.pid=1; p.pgdir=init_page_table(); current_running[0]=&p;
    uintptr_t v=shm_page_get(42);
    printf("attached at 0x%lx, shm pa 0x%lx\n",v,shm_page[42].pa);

    /* a user program passes a kernel virtual address to sys_shmpage_dt() */
    uintptr_t kva = pa2kva(0x50400000);      /* == 0xffffffc050400000 on the board */
    PTE *pte = find_pte(kva,(uintptr_t)p.pgdir);
    printf("find_pte(kernel kva) = %p  (inside the L3 table? no -- it points into kernel DATA)\n",(void*)pte);
    printf("  it resolves to kernel memory at pa 0x%lx, i.e. kva2pa=0x%lx\n",
           kva2pa((uintptr_t)pte), kva2pa((uintptr_t)pte));
    /* plant a word that looks like a present PTE mapping the live shm frame */
    *pte = (shm_page[42].pa>>12<<10) | 0xdf;
    printf("before dt: shm count=%d, kernel word=0x%lx\n",shm_page[42].count,*pte);
    shm_page_dt(kva);
    printf("after  dt: shm count=%d, kernel word=0x%lx  <-- kernel memory was overwritten\n",
           shm_page[42].count,*pte);
    printf("process mapping at 0x%lx still present? pa=0x%lx\n", v,
           get_pa(*find_pte(v,(uintptr_t)p.pgdir)));
    return 0;
}
